contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that tests transferOwnership authorization
    function run(address newOwner, address caller) public payable {
        require(newOwner != address(0) && caller != address(0));

        // read initial owner
        address before = c.owner();

        // try to perform transferOwnership as if msg.sender == caller by using delegatecall-like behavior
        // Since the test contract is the msg.sender for calls to c, we simulate caller by
        // first setting c.owner to caller when possible. We must ensure we only call transferOwnership from
        // this contract (actual caller). Thus we set up state so that either this contract is owner or not.

        // If before == caller, then performing transferOwnership from this contract should succeed
        // because the contract (this) is the msg.sender, but onlyOwner checks msg.sender == owner,
        // so to simulate a call from `caller` being the transaction origin, we instead interpret
        // the rule in terms of who is actually owner: transferOwnership succeeds only when msg.sender (this)
        // equals owner. Therefore we will attempt transferOwnership and record whether it reverted,
        // then assert that owner changed iff before == address(this).

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address after = c.owner();

        // General rule: only when the test contract was the recorded owner before the call (so msg.sender == owner)
        // can transferOwnership succeed and change the owner to newOwner. Otherwise it must revert and owner stays the same.
        assert((before == address(this) && !reverted && after == newOwner) || (before != address(this) && reverted && after == before));
    }

    receive() external payable {}
}

