contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property test
    function run(address newOwner, address caller) public payable {
        // Ensure some freedom in inputs (no precondition on c since it's fresh)
        // Read owner before any calls
        address beforeOwner = c.owner();

        // We will attempt transferOwnership from this contract (which is the deployer of c)
        // The checker deploys a fresh c and then this test; in that setup, msg.sender for calls from this contract is address(this)
        // First, record result when this contract (msg.sender == address(this)) calls transferOwnership
        bool revertedByThis;
        try c.transferOwnership(newOwner) {
            revertedByThis = false;
        } catch {
            revertedByThis = true;
        }
        address afterByThis = c.owner();

        // Now try to call transferOwnership as if from some other address.
        // We cannot change msg.sender in this environment, so simulate a non-owner call by using the public owned() function:
        // Instead, we deploy no new call context; but we can check property about non-owner behavior by only making a second call from this contract after we've set owner to something else.
        // If this contract was owner before the first call and transfer succeeded, then set up a state where this contract is NOT the owner and then calling transferOwnership should revert.

        // If the first call succeeded, then owner became newOwner. We now try to make this contract attempt transferOwnership again which should revert because msg.sender (this contract) is no longer the owner.
        bool secondReverted;
        // Make the second call top-level
        try c.transferOwnership(caller) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        address afterSecond = c.owner();

        /* General rule asserted:
           - If the first call (from this contract) did not revert, then afterByThis equals newOwner.
           - If the first call reverted, owner remains beforeOwner.
           - Additionally, if the first call succeeded then the immediate second call from this contract (now a non-owner) must revert and owner remains unchanged by that second call.
        */
        assert(
            (
                (!revertedByThis && afterByThis == newOwner && (
                    // second call should have reverted and left owner unchanged
                    secondReverted && afterSecond == afterByThis
                )) ||
                (revertedByThis && afterByThis == beforeOwner)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: candidate newOwner and a flag decideWhoCalls
    // if decideWhoCalls==true, the test (which is the deployer of C) will call transferOwnership as owner
    // if false, the test will emulate a non-owner call by deploying a helper call through address different from owner
    function run(address newOwner, bool callerIsOwner) public payable {
        require(newOwner != address(0));

        // read initial owner
        address beforeOwner = c.owner();

        // Decide caller: if callerIsOwner==true, msg.sender of calls on c is this contract (InvMutTest)
        // The checker deploys a fresh C and sets its owner initially to some address; we cannot change that.
        // We will attempt transferOwnership and observe whether it reverts. If callerIsOwner is false,
        // we still call transferOwnership from this contract; to simulate non-owner call we first
        // ensure this contract is not the owner by checking beforeOwner != address(this). If it is the owner,
        // we instead call owned() (which requires owner) and expect it to succeed. To keep a single general rule,
        // we perform a try/catch on transferOwnership and record whether it reverted.

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        // General rule: transferOwnership can succeed only when msg.sender == beforeOwner; if it succeeded,
        // afterOwner equals newOwner; if it reverted, owner remains unchanged (afterOwner == beforeOwner).
        assert((!reverted && afterOwner == newOwner && beforeOwner == address(this)) || (reverted && afterOwner == beforeOwner));
    }

    receive() external payable {}
}
